dashboard.definition:
{
    "title": "OP-Management",
    "description": "OP-Management: Tagesplan aller OP-Saele, Status, Auslastung und abgesetzte Faelle",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Abteilung",
            "options": {
                "items": [
                    {
                        "label": "Alle Abteilungen",
                        "value": "*"
                    },
                    {
                        "label": "Innere Medizin (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Kardiologie (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurologie (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Onkologie (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "Allgemeinchirurgie (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Unfallchirurgie/Orthopaedie (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urologie (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anaesthesie/OP (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensivmedizin (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Notaufnahme (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiologie (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynaekologie/Geburtshilfe (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Paediatrie (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatrie (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "room": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_today": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:or:case\" (type=plan OR type=milestone) earliest=@d latest=+1d department=\"$dept$\"\n| stats latest(planned_start) as planned_start latest(planned_end) as planned_end min(actual_start) as actual_start max(actual_end) as actual_end latest(status) as status latest(procedure) as procedure latest(department) as department latest(delay_min) as delay_min by room case_id",
                "enableSmartSources": true
            },
            "name": "OP-Faelle heute"
        },
        "ds_k_cases": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| stats count as \"Faelle heute\""
            }
        },
        "ds_k_done": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| where isnotnull(actual_end) | stats count as Abgeschlossen"
            }
        },
        "ds_k_cancel": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| where like(status, \"abgesetzt%\") | stats count as Abgesetzt"
            }
        },
        "ds_k_delay": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| where isnotnull(actual_start) | eval d=(actual_start - planned_start) / 60 | stats avg(d) as \"Verspaetung (min)\" | eval \"Verspaetung (min)\"=round('Verspaetung (min)', 0)"
            }
        },
        "ds_rooms": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:or:case\" type=room_status earliest=-10m\n| stats latest(phase) as phase latest(procedure) as procedure latest(department) as department latest(delay_min) as delay_min latest(cases_done) as done latest(cases_today) as total latest(cases_cancelled) as cancelled latest(utilization_pct) as util by room suite",
                "enableSmartSources": true
            },
            "name": "Saalstatus"
        },
        "ds_k_running": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rooms",
                "query": "| where phase=\"OP laeuft\" OR phase=\"Einleitung\" OR phase=\"Ausleitung\" | stats count as \"Saele in Betrieb\""
            }
        },
        "ds_k_util": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rooms",
                "query": "| stats avg(util) as Auslastung | eval Auslastung=round(Auslastung, 1)"
            }
        },
        "ds_room_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rooms",
                "query": "| eval Faelle=done.\" / \".total, Phase=phase\n| table room suite Phase procedure department delay_min Faelle cancelled util\n| rename room as Saal suite as Bereich procedure as Eingriff department as Abteilung delay_min as \"Verspaetung (min)\" cancelled as Abgesetzt util as \"Auslastung %\""
            }
        },
        "ds_util": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rooms",
                "query": "| table room util | rename room as Saal util as \"Auslastung %\""
            }
        },
        "ds_cancelled": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:or:case\" type=plan status=\"abgesetzt*\" earliest=@d latest=+1d\n| stats latest(procedure) as Eingriff latest(department) as Abteilung latest(planned_start) as ps latest(blood_units_planned) as EK by room case_id\n| eval Geplant=strftime(ps, \"%H:%M\") | table room case_id Eingriff Abteilung Geplant EK | rename room as Saal case_id as Fall EK as \"EK geplant\"",
                "enableSmartSources": true
            }
        },
        "ds_by_dept": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| stats count as Faelle by department | sort - Faelle | rename department as Abteilung"
            }
        },
        "ds_cases_room": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:or:case\" (type=plan OR type=milestone) earliest=@d latest=+1d department=\"$dept$\"\n| stats latest(planned_start) as planned_start latest(planned_end) as planned_end min(actual_start) as actual_start max(actual_end) as actual_end latest(status) as status latest(procedure) as procedure latest(department) as department latest(delay_min) as delay_min by room case_id | search room=\"$room$\"\n| eval Geplant=strftime(planned_start, \"%H:%M\").\"–\".strftime(planned_end, \"%H:%M\"), Beginn=strftime(actual_start, \"%H:%M\"), Ende=strftime(actual_end, \"%H:%M\")\n| sort planned_start | table room case_id procedure department Geplant Beginn Ende status\n| rename room as Saal case_id as Fall procedure as Eingriff department as Abteilung status as Status",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_care_on.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_beds",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_diag": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_diag.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
