        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_cases"
            },
            "options": {
                "majorColor": "#34e2a0",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_done"
            },
            "options": {
                "majorColor": "#22d3ee",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_running"
            },
            "options": {
                "majorColor": "#a78bfa",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_delay"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 15,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 15,
                        "to": 30,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 30,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_util"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 40,
                        "value": "#ff4d6d"
                    },
                    {
                        "from": 40,
                        "to": 60,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 60,
                        "value": "#34e2a0"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_cancel"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
