                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "room",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_08": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_room_table"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 12,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Verspaetung (min)": {
                        "rowBackgroundColors": "> table | seriesByName(\"Verspaetung (min)\") | rangeValue(range_2)"
                    }
